$('delete-item').onclick=async()=>{if(recorder||busy)return;if(!current())return;checkpoint();project.items=project.items.filter(i=>i.id!==selected);selected=null;renderItems();await persist();toast('기록 삭제 · 되돌리기 가능');};$('undo').onclick=async()=>{if(recorder||busy||!history.length)return;clearTimeout(saveTimer);project=history.pop();if(!project.items.some(i=>i.id===selected))selected=null;$('project-title').value=project.title;$('undo').disabled=!history.length;renderItems();renderReport();await persist();toast('최근 작업을 되돌렸어요');};
$('save-project').onclick=async()=>{try{await persist();toast('라이브러리에 저장했어요');}catch{}};$('backup').onclick=async()=>{await persist().catch(()=>{});download(new Blob([JSON.stringify(project)],{type:'application/json'}),`${project.id}.bogo.json`);};$('import-project').onclick=()=>$('backup-input').click();$('backup-input').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>200*1024*1024)throw Error('200MB 이하의 백업을 선택해 주세요');const p=validateProject(JSON.parse(await file.text()));p.id=`${p.id}-복원-${crypto.randomUUID().slice(0,4)}`;p.updatedAt=new Date().toISOString();await transaction('readwrite',s=>s.put(p));await renderLibrary();toast('백업을 복원했어요');}catch(e){toast(e.message);}finally{e.target.value='';}};
$('reset-project').onclick=async()=>{if(recorder||busy)return;if(await confirmAction('작업 전체를 초기화할까요?','사진, 영상, 음성 메모와 보고서를 비웁니다. 되돌리기로 복구할 수 있습니다.')){checkpoint();project.items=[];project.report='';project.feedback='';selected=null;renderItems();renderReport();await persist();}};$('reset-report').onclick=async()=>{if(busy)return;if(await confirmAction('작성한 보고서를 지울까요?','현장 기록은 보관하고 보고서 본문만 지웁니다.')){checkpoint();project.report='';renderReport();await persist();}};
function showSettings(){ $('report-length').value=settings.length;$('length-value').value=`${settings.length}자`;$('photo-limit').value=settings.photos;$('generation-mode').value=settings.mode;$('api-endpoint').value=settings.endpoint;$('settings-dialog').showModal();}$('settings').onclick=showSettings;$('report-settings').onclick=showSettings;$('report-length').oninput=e=>$('length-value').value=e.target.value+'자';$('save-settings').onclick=e=>{e.preventDefault();settings={length:Number($('report-length').value),photos:Math.max(0,Math.min(50,Number($('photo-limit').value)||0)),mode:$('generation-mode').value,endpoint:$('api-endpoint').value.trim()||'/api/report'};localStorage.setItem('bogo-settings',JSON.stringify(settings));$('settings-dialog').close();if(project)renderReport();toast('설정을 저장했어요');};$('generate').onclick=generate;
$('feedback-voice').onclick=()=>{if(speech){speech.stop();speech=null;$('feedback-voice').textContent='♩';}else{startSpeech('feedback');$('feedback-voice').textContent='■';}};
$('share').onclick=async()=>{if(!requireReport())return;try{const file=new File([reportHtml()],`${project.id}.html`,{type:'text/html'});if(navigator.canShare?.({files:[file]}))await navigator.share({title:project.title,text:'외근 보고서',files:[file]});else if(navigator.share)await navigator.share({title:project.title,text:project.report});else{await navigator.clipboard.writeText(project.report);toast('본문을 복사했어요. 카카오톡에 붙여 넣으세요.');}}catch(e){if(e.name!=='AbortError')toast('파일 저장 후 카카오톡에서 첨부해 주세요.');}};$('export-report').onclick=()=>{if(requireReport())download(new Blob([reportHtml()],{type:'text/html'}),`${project.id}.html`);};$('print-report').onclick=()=>{if(!requireReport())return;const w=window.open('','_blank');if(!w)return toast('팝업을 허용해 주세요');w.document.write(reportHtml());w.document.close();w.onload=()=>w.print();};
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(recorder)stopRecording();else stopCamera();if(project)persist().catch(()=>{});speech?.stop();}});window.addEventListener('beforeunload',e=>{if(recorder||busy){e.preventDefault();e.returnValue='';}});$('today').textContent=new Date().toLocaleDateString('ko-KR',{year:'numeric',month:'long',day:'numeric',weekday:'long'});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
